import { useState } from 'react';
import { JxButton, JxInput } from '@jinx-ui/react';

export type RegistrationData = {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
};

type Props = {
  onSubmit: (data: RegistrationData) => void;
};

const STEPS = ['Контакты', 'Адрес', 'Проверка'] as const;

const EMPTY: RegistrationData = {
  name: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
};

const LABELS: Record<keyof RegistrationData, string> = {
  name: 'Имя',
  email: 'E-mail',
  phone: 'Телефон',
  country: 'Страна',
  city: 'Город',
  street: 'Улица, дом',
  zip: 'Индекс',
};

export default function RegistrationWizard({ onSubmit }: Props) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>(EMPTY);

  const update = (key: keyof RegistrationData) => (value: string) =>
    setData((prev) => ({ ...prev, [key]: value }));

  const isLast = step === STEPS.length - 1;

  const field = (key: keyof RegistrationData, type = 'text') => (
    <JxInput
      label={LABELS[key]}
      type={type}
      value={data[key]}
      onValueChange={update(key)}
    />
  );

  return (
    <section
      aria-label="Регистрация"
      style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-5)' }}
    >
      <ol
        style={{
          display: 'flex',
          gap: 'var(--jx-space-2)',
          listStyle: 'none',
          margin: 0,
          padding: 0,
        }}
      >
        {STEPS.map((title, index) => (
          <li key={title} style={{ flex: 1 }}>
            <JxButton
              variant={index === step ? 'primary' : 'secondary'}
              disabled={index > step}
              aria-current={index === step ? 'step' : undefined}
              onClick={() => setStep(index)}
            >
              {index + 1}. {title}
            </JxButton>
          </li>
        ))}
      </ol>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4)' }}>
        {step === 0 && (
          <>
            {field('name')}
            {field('email', 'email')}
            {field('phone', 'tel')}
          </>
        )}

        {step === 1 && (
          <>
            {field('country')}
            {field('city')}
            {field('street')}
            {field('zip')}
          </>
        )}

        {step === 2 && (
          <dl
            style={{
              display: 'grid',
              gridTemplateColumns: 'max-content 1fr',
              gap: 'var(--jx-space-2) var(--jx-space-4)',
              margin: 0,
            }}
          >
            {(Object.keys(LABELS) as Array<keyof RegistrationData>).map((key) => (
              <div key={key} style={{ display: 'contents' }}>
                <dt style={{ color: 'var(--jx-color-text-muted)' }}>{LABELS[key]}</dt>
                <dd style={{ margin: 0 }}>{data[key] || '—'}</dd>
              </div>
            ))}
          </dl>
        )}
      </div>

      <div style={{ display: 'flex', gap: 'var(--jx-space-3)' }}>
        <JxButton
          variant="secondary"
          disabled={step === 0}
          onClick={() => setStep((prev) => prev - 1)}
        >
          Назад
        </JxButton>
        <JxButton
          variant="primary"
          onClick={() => (isLast ? onSubmit(data) : setStep((prev) => prev + 1))}
        >
          {isLast ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </section>
  );
}

